import puppeteer from "puppeteer";

/**
 * Information needed to complete online credit freeze / opt‑out forms.
 * Only include the minimum necessary fields. Sensitive values (SSN/DOB) should
 * never be logged or persisted. The caller should supply them at runtime.
 */
export interface FreezeUserInfo {
  /** Given name of the consumer */
  firstName: string;
  /** Family name of the consumer */
  lastName: string;
  /** Primary residential street address */
  address: string;
  /** City portion of the address */
  city: string;
  /** Two‑letter state code */
  state: string;
  /** Five‑digit ZIP code */
  zip: string;
  /** Full nine‑digit SSN if requested (###‑##‑####) */
  ssn?: string;
  /** Date of birth in YYYY‑MM‑DD format */
  dob?: string;
  /** Contact phone number */
  phone?: string;
  /** Contact email address */
  email?: string;
}

/**
 * Launch a headless browser using Puppeteer. A shared helper to ensure the
 * browser closes when done. If your Replit environment requires specific
 * Chromium flags (e.g. to run in a container), adjust the launch options
 * accordingly. You may also configure `args` via env vars if needed.
 */
async function launchBrowser() {
  return await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
    ],
  });
}

/**
 * Freeze your LexisNexis consumer file via the online portal. The form
 * requires identifying information (name, address, SSN, date of birth). If
 * additional verification steps or CAPTCHAs are encountered, this helper will
 * throw and the caller should handle the error and possibly prompt the
 * consumer to complete the process manually. Selectors are based on the page
 * structure as of October 2025; they may change and should be updated
 * accordingly.
 */
export async function freezeLexisNexis(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://consumer.risk.lexisnexis.com/freeze#/freeze-self', { waitUntil: 'domcontentloaded' });
    // Example: fill out basic identity details. Adjust selectors as needed.
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="address1"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.ssn) {
      // Assume form splits SSN into parts; adapt if necessary.
      const ssnDigits = info.ssn.replace(/\D/g, '');
      await page.type('input[name="ssn"]', ssnDigits);
    }
    if (info.dob) {
      await page.type('input[name="dob"]', info.dob);
    }
    if (info.phone) {
      await page.type('input[name="phone"]', info.phone);
    }
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    // Submit the form. Many freeze pages use a button with text like
    // "Continue" or "Submit"; adjust the selector accordingly.
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * Request a copy of your LexisNexis consumer report. This opt‑out flow is
 * separate from the freeze. Basic identity information is required.
 */
export async function requestLexisNexisReport(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://consumer.risk.lexisnexis.com/request', { waitUntil: 'domcontentloaded' });
    // Fill out the form similarly to freeze
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="address1"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.ssn) {
      const ssnDigits = info.ssn.replace(/\D/g, '');
      await page.type('input[name="ssn"]', ssnDigits);
    }
    if (info.dob) {
      await page.type('input[name="dob"]', info.dob);
    }
    if (info.phone) {
      await page.type('input[name="phone"]', info.phone);
    }
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * Submit an opt‑out request to Cotality for your consumer data. Cotality
 * (formerly iovation/SageStream) provides a privacy form under their privacy
 * policy. This helper navigates to the page and populates the required
 * fields. If the page URL changes, update the goto URL accordingly.
 */
export async function optOutCotality(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://www.cotality.com/legal/privacy-policy', { waitUntil: 'domcontentloaded' });
    // This page often contains a link or form for opt‑out. You may need to
    // click through to the request form. Replace selectors accordingly.
    // Example: click a link labelled "Submit a privacy request"
    const link = await page.$x("//a[contains(text(), 'privacy request')]");
    if (link.length > 0) {
      await Promise.all([
        page.waitForNavigation({ waitUntil: 'networkidle0' }),
        link[0].click(),
      ]);
    }
    // Once on the form page, populate fields.
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="addressLine1"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    // Some forms require you to check an opt‑out reason; check the first
    // available checkbox or radio button.
    const checkbox = await page.$('input[type="checkbox"]');
    if (checkbox) {
      await checkbox.click();
    }
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * Opt out of Innovis marketing and information sharing. The Innovis site
 * provides a simple opt‑out form for consumers. Supply the required
 * identity fields and submit.
 */
export async function optOutInnovis(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://www.innovis.com/personal/optOutOptIn', { waitUntil: 'domcontentloaded' });
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="street"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.phone) {
      await page.type('input[name="phone"]', info.phone);
    }
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    // Select opt‑out radio button; adjust if site uses checkboxes
    const optOutRadio = await page.$('input[type="radio"][value="optout"]');
    if (optOutRadio) {
      await optOutRadio.click();
    }
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * Opt out of prescreened credit and insurance offers at OptOutPrescreen.com.
 * This form requires basic identity details and allows either electronic or
 * mail confirmation. Here we select the electronic (online) opt‑out. A
 * confirmation email may be sent to finalize the request, so ensure a valid
 * email is provided.
 */
export async function optOutPrescreen(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://www.optoutprescreen.com/selection', { waitUntil: 'domcontentloaded' });
    // Choose the electronic opt out option
    const onlineRadio = await page.$('input[type="radio"][value="ELECTRONIC"]');
    if (onlineRadio) {
      await onlineRadio.click();
    }
    await page.click('button[type="submit"]');
    // Wait for personal info form
    await page.waitForSelector('input[name="firstName"]');
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="address"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.ssn) {
      const ssnDigits = info.ssn.replace(/\D/g, '');
      await page.type('input[name="ssn"]', ssnDigits);
    }
    if (info.dob) {
      await page.type('input[name="dob"]', info.dob);
    }
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * Opt out of SageStream (now part of LexisNexis). The opt out page is
 * hosted at sagestreamllc.com. Provide the consumer information and
 * submit the form. As with other providers, there may be CAPTCHAs or
 * additional verification steps which cannot be bypassed programmatically.
 */
export async function optOutSageStream(info: FreezeUserInfo): Promise<void> {
  const browser = await launchBrowser();
  const page = await browser.newPage();
  try {
    await page.goto('https://www.sagestreamllc.com/opt-out-opt-in/index.html', { waitUntil: 'domcontentloaded' });
    await page.type('input[name="firstName"]', info.firstName);
    await page.type('input[name="lastName"]', info.lastName);
    await page.type('input[name="address"]', info.address);
    await page.type('input[name="city"]', info.city);
    await page.select('select[name="state"]', info.state);
    await page.type('input[name="zip"]', info.zip);
    if (info.email) {
      await page.type('input[name="email"]', info.email);
    }
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle0' }),
      page.click('button[type="submit"]'),
    ]);
  } finally {
    await browser.close();
  }
}

/**
 * The master helper that orchestrates all freezes and opt‑outs for a given
 * consumer. It runs each provider flow sequentially. If any step throws
 * an error (for example due to a CAPTCHA), the error is propagated so the
 * caller can log it and possibly inform the consumer to complete that
 * provider manually. To run individual providers, call their helpers
 * directly.
 */
export async function runAllFreezes(info: FreezeUserInfo): Promise<void> {
  await freezeLexisNexis(info);
  await requestLexisNexisReport(info);
  await optOutCotality(info);
  await optOutInnovis(info);
  await optOutPrescreen(info);
  await optOutSageStream(info);
}

server/adminRoutes.ts.content:
import { Router } from "express";
import { db } from "./db";
import { users, mailBatches, deliveryEvents, clientResponses, adminAuditLogs } from "@shared/schema";
import { eq, desc, sql } from "drizzle-orm";
import { adminOnly } from "./adminOnly";
import { logAudit } from "./audit";
import { notificationService } from "./services/notificationService";
import { mintActionToken } from "./oneTimeToken";
import { letterGeneratorService } from "./services/letterGenerator";
import { click2mailService } from "./services/click2mail";

export const adminRouter = Router();

// All admin routes require admin role
adminRouter.use(adminOnly);

// GET /api/admin/whoami - Admin session introspection for testing
adminRouter.get("/whoami", (req, res) => {
  const u = (req as any).user || {};
  const email = u?.claims?.email || null;
  const role = u?.role || u?.claims?.role || "user";
  res.json({ id: u?.claims?.sub || null, email, isAdmin: role === "admin" });
});

// GET /api/admin/stats - Admin dashboard statistics
adminRouter.get("/stats", async (req, res) => {
  try {
    const totalUsers = await db.select({ count: sql<number>`count(*)` }).from(users);
    const totalCases = await db.select({ count: sql<number>`count(DISTINCT case_id)` }).from(mailBatches);
    const totalLetters = await db.select({ count: sql<number>`count(*)` }).from(mailBatches);
    const pendingResponses = await db.select({ count: sql<number>`count(*)` }).from(clientResponses);

    res.json({
      totalUsers: totalUsers[0]?.count || 0,
      totalCases: totalCases[0]?.count || 0,
      totalLetters: totalLetters[0]?.count || 0,
      pendingResponses: pendingResponses[0]?.count || 0,
    });
  } catch (error) {
    console.error("Error fetching admin stats:", error);
    res.status(500).json({ message: "Failed to fetch stats" });
  }
});

// GET /api/admin/users - List all users
adminRouter.get("/users", async (req, res) => {
  try {
    const allUsers = await db.select().from(users).orderBy(desc(users.createdAt));
    res.json(allUsers);
  } catch (error) {
    console.error("Error fetching users:", error);
    res.status(500).json({ message: "Failed to fetch users" });
  }
});

// PUT /api/admin/users/:id/role - Change user role
adminRouter.put("/users/:id/role", async (req: any, res) => {
  try {
    const { id } = req.params;
    const { role } = req.body;

    if (!['user', 'admin'].includes(role)) {
      return res.status(400).json({ message: "Invalid role" });
    }

    await db.update(users).set({ role }).where(eq(users.id, id));

    const actorId = req.user.id;
    await logAudit(actorId, 'update_user_role', 'user', id, { newRole: role });

    res.json({ message: "Role updated successfully" });
  } catch (error) {
    console.error("Error updating user role:", error);
    res.status(500).json({ message: "Failed to update role" });
  }
});

// GET /api/admin/cases - Latest case snapshot per caseId
adminRouter.get("/cases", async (req, res) => {
  try {
    const cases = await db
      .select({
        caseId: mailBatches.caseId,
        clientId: mailBatches.clientId,
        clientEmail: users.email,
        clientName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        bureau: mailBatches.bureau,
        round: mailBatches.round,
        status: mailBatches.status,
        createdAt: mailBatches.createdAt,
      })
      .from(mailBatches)
      .leftJoin(users, eq(mailBatches.clientId, users.id))
      .orderBy(desc(mailBatches.createdAt));

    res.json(cases);
  } catch (error) {
    console.error("Error fetching cases:", error);
    res.status(500).json({ message: "Failed to fetch cases" });
  }
});

// GET /api/admin/letters - All mail batches with delivery info
adminRouter.get("/letters", async (req, res) => {
  try {
    const letters = await db
      .select({
        id: mailBatches.id,
        caseId: mailBatches.caseId,
        clientId: mailBatches.clientId,
        clientEmail: users.email,
        clientName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        bureau: mailBatches.bureau,
        round: mailBatches.round,
        status: mailBatches.status,
        click2mailJobId: mailBatches.click2mailJobId,
        uspsTracking: mailBatches.uspsTracking,
        proofUrl: mailBatches.proofUrl,
        createdAt: mailBatches.createdAt,
      })
      .from(mailBatches)
      .leftJoin(users, eq(mailBatches.clientId, users.id))
      .orderBy(desc(mailBatches.createdAt));

    // Get latest delivery event for each batch
    const enrichedLetters = await Promise.all(
      letters.map(async (letter) => {
        const latestEvent = await db
          .select()
          .from(deliveryEvents)
          .where(eq(deliveryEvents.batchId, letter.id))
          .orderBy(desc(deliveryEvents.createdAt))
          .limit(1);

        return {
          ...letter,
          latestEvent: latestEvent[0] || null,
        };
      })
    );

    res.json(enrichedLetters);
  } catch (error) {
    console.error("Error fetching letters:", error);
    res.status(500).json({ message: "Failed to fetch letters" });
  }
});

// GET /api/admin/responses - Client uploaded responses
adminRouter.get("/responses", async (req, res) => {
  try {
    const responses = await db
      .select({
        id: clientResponses.id,
        caseId: clientResponses.caseId,
        clientId: clientResponses.clientId,
        clientEmail: users.email,
        clientName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        round: clientResponses.round,
        fileUrl: clientResponses.fileUrl,
        ocrText: clientResponses.ocrText,
        analysisJson: clientResponses.analysisJson,
        createdAt: clientResponses.createdAt,
      })
      .from(clientResponses)
      .leftJoin(users, eq(clientResponses.clientId, users.id))
      .orderBy(desc(clientResponses.createdAt));

    res.json(responses);
  } catch (error) {
    console.error("Error fetching responses:", error);
    res.status(500).json({ message: "Failed to fetch responses" });
  }
});

// POST /api/admin/letters/:id/remind-day34 - Send Day-34 reminder
adminRouter.post("/letters/:id/remind-day34", async (req: any, res) => {
  try {
    const { id } = req.params;

    const batch = await db
      .select()
      .from(mailBatches)
      .where(eq(mailBatches.id, id))
      .limit(1);

    if (!batch[0]) {
      return res.status(404).json({ message: "Mail batch not found" });
    }

    const client = await db
      .select()
      .from(users)
      .where(eq(users.id, batch[0].clientId))
      .limit(1);

    if (!client[0] || !client[0].email) {
      return res.status(404).json({ message: "Client not found" });
    }

    // Mint tokens for Yes/No/Upload
    const yesToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "yes");
    const noToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "no");
    const uploadToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "upload");

    // Send notification
    await notificationService.sendDay34FollowUp(
      client[0].email,
      client[0].firstName || 'Client',
      batch[0].bureau,
      batch[0].round,
      yesToken,
      noToken,
      uploadToken
    );

    const actorId = req.user.id;
    await logAudit(actorId, 'send_day34_reminder', 'mail_batch', id, {
      caseId: batch[0].caseId,
      bureau: batch[0].bureau,
      round: batch[0].round,
    });

    res.json({ message: "Day-34 reminder sent successfully" });
  } catch (error) {
    console.error("Error sending Day-34 reminder:", error);
    res.status(500).json({ message: "Failed to send reminder" });
  }
});

// POST /api/admin/letters/:id/remail - Re-mail a letter
adminRouter.post("/letters/:id/remail", async (req: any, res) => {
  try {
    const { id } = req.params;

    const batch = await db
      .select()
      .from(mailBatches)
      .where(eq(mailBatches.id, id))
      .limit(1);

    if (!batch[0]) {
      return res.status(404).json({ message: "Mail batch not found" });
    }

    const client = await db
      .select()
      .from(users)
      .where(eq(users.id, batch[0].clientId))
      .limit(1);

    if (!client[0]) {
      return res.status(404).json({ message: "Client not found" });
    }

    // Regenerate letter PDF (simplified - you'd use actual letter generation)
    const pdfUrl = `/files/letter_${Date.now()}.pdf`;

    // Submit to Click2Mail (if configured)
    if (process.env.CLICK2MAIL_API_KEY) {
      const jobId = await click2mailService.submitLetter({
        recipientName: "Credit Bureau",
        recipientAddress: "123 Bureau St",
        recipientCity: batch[0].bureau,
        recipientState: "NY",
        recipientZip: "10001",
        pdfUrl,
      });

      await db
        .update(mailBatches)
        .set({ click2mailJobId: jobId, status: 'queued' })
        .where(eq(mailBatches.id, id));
    }

    const actorId = req.user.id;
    await logAudit(actorId, 'remail_letter', 'mail_batch', id, {
      caseId: batch[0].caseId,
      bureau: batch[0].bureau,
      round: batch[0].round,
    });

    res.json({ message: "Letter remailed successfully" });
  } catch (error) {
    console.error("Error remailing letter:", error);
    res.status(500).json({ message: "Failed to remail letter" });
  }
});

// GET /api/admin/audit - Audit logs
adminRouter.get("/audit", async (req, res) => {
  try {
    const limit = parseInt(req.query.limit as string) || 200;

    const logs = await db
      .select({
        id: adminAuditLogs.id,
        actorId: adminAuditLogs.actorId,
        actorEmail: users.email,
        action: adminAuditLogs.action,
        targetType: adminAuditLogs.targetType,
        targetId: adminAuditLogs.targetId,
        meta: adminAuditLogs.meta,
        createdAt: adminAuditLogs.createdAt,
      })
      .from(adminAuditLogs)
      .leftJoin(users, eq(adminAuditLogs.actorId, users.id))
      .orderBy(desc(adminAuditLogs.createdAt))
      .limit(limit);

    res.json(logs);
  } catch (error) {
    console.error("Error fetching audit logs:", error);
    res.status(500).json({ message: "Failed to fetch audit logs" });
  }
});

// GET /api/admin/cases/:id - Case timeline
adminRouter.get("/cases/:id", async (req, res) => {
  try {
    const { id: caseId } = req.params;

    // Get all mail batches for this case
    const batches = await db
      .select()
      .from(mailBatches)
      .where(eq(mailBatches.caseId, caseId))
      .orderBy(desc(mailBatches.createdAt));

    // Get delivery events for each batch
    const timeline = await Promise.all(
      batches.map(async (batch) => {
        const events = await db
          .select()
          .from(deliveryEvents)
          .where(eq(deliveryEvents.batchId, batch.id))
          .orderBy(desc(deliveryEvents.createdAt));

        return {
          batch,
          events,
        };
      })
    );

    // Get client responses for this case
    const responses = await db
      .select()
      .from(clientResponses)
      .where(eq(clientResponses.caseId, caseId))
      .orderBy(desc(clientResponses.createdAt));

    res.json({
      caseId,
      timeline,
      responses,
    });
  } catch (error) {
    console.error("Error fetching case timeline:", error);
    res.status(500).json({ message: "Failed to fetch case timeline" });
  }
});

// GET /api/admin/cases/eligible-day34 - Cases eligible for Day-34 follow-ups
adminRouter.get("/cases/eligible-day34", async (req, res) => {
  try {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - 34);

    const eligible = await db
      .select({
        id: mailBatches.id,
        caseId: mailBatches.caseId,
        clientId: mailBatches.clientId,
        clientEmail: users.email,
        clientName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        bureau: mailBatches.bureau,
        round: mailBatches.round,
        status: mailBatches.status,
        createdAt: mailBatches.createdAt,
      })
      .from(mailBatches)
      .leftJoin(users, eq(mailBatches.clientId, users.id))
      .where(sql`${mailBatches.createdAt} <= ${cutoff}`)
      .orderBy(desc(mailBatches.createdAt));

    res.json(eligible);
  } catch (error) {
    console.error("Error fetching eligible cases:", error);
    res.status(500).json({ message: "Failed to fetch eligible cases" });
  }
});

// POST /api/admin/cases/bulk-remind-day34 - Bulk send Day-34 reminders
adminRouter.post("/cases/bulk-remind-day34", async (req: any, res) => {
  try {
    const { batchIds } = req.body;

    if (!Array.isArray(batchIds) || batchIds.length === 0) {
      return res.status(400).json({ message: "Invalid batch IDs" });
    }

    const results = [];

    for (const batchId of batchIds) {
      try {
        const batch = await db
          .select()
          .from(mailBatches)
          .where(eq(mailBatches.id, batchId))
          .limit(1);

        if (!batch[0]) continue;

        const client = await db
          .select()
          .from(users)
          .where(eq(users.id, batch[0].clientId))
          .limit(1);

        if (!client[0] || !client[0].email) continue;

        const yesToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "yes");
        const noToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "no");
        const uploadToken = await mintActionToken(batch[0].clientId, batch[0].caseId, "upload");

        await notificationService.sendDay34FollowUp(
          client[0].email,
          client[0].firstName || 'Client',
          batch[0].bureau,
          batch[0].round,
          yesToken,
          noToken,
          uploadToken
        );

        results.push({ batchId, success: true });
      } catch (error) {
        results.push({ batchId, success: false, error: String(error) });
      }
    }

    const actorId = req.user.id;
    await logAudit(actorId, 'bulk_day34_reminder', 'mail_batches', 'multiple', {
      count: batchIds.length,
      results,
    });

    res.json({
      message: `Sent ${results.filter(r => r.success).length} of ${batchIds.length} reminders`,
      results,
    });
  } catch (error) {
    console.error("Error sending bulk reminders:", error);
    res.status(500).json({ message: "Failed to send bulk reminders" });
  }
});

server/services/click2mail.ts.content:
interface Click2MailLetter {
  addressFrom: {
    name: string;
    address1: string;
    city: string;
    state: string;
    zip: string;
  };
  addressTo: {
    name: string;
    address1: string;
    city: string;
    state: string;
    zip: string;
  };
  document: string; // Base64 encoded PDF
}

export class Click2MailService {
  private apiKey: string;
  private baseUrl = "https://rest.click2mail.com/molpro/restservice.svc";

  constructor() {
    this.apiKey = process.env.CLICK2MAIL_API_KEY || process.env.CLICK2MAIL_KEY || "";
    if (!this.apiKey) {
      console.warn("Click2Mail API key not configured");
    }
  }

  async sendLetter(letter: Click2MailLetter): Promise<{
    jobId: string;
    trackingNumber: string;
    status: string;
  }> {
    if (!this.apiKey) {
      throw new Error("Click2Mail API key not configured");
    }

    try {
      const response = await fetch(`${this.baseUrl}/jobs`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify({
          ...letter,
          productionMode: process.env.NODE_ENV === "production",
          mailClass: "FIRST_CLASS",
          color: "FULL_COLOR",
          envelope: "WHITE_STANDARD",
          pages: 1,
        }),
      });

      if (!response.ok) {
        throw new Error(`Click2Mail API error: ${response.status} ${response.statusText}`);
      }

      const result = await response.json();

      return {
        jobId: result.jobId,
        trackingNumber: result.trackingNumber,
        status: result.status,
      };
    } catch (error: any) {
      console.error("Error sending letter via Click2Mail:", error);
      throw new Error("Failed to send letter: " + (error?.message || "Unknown error"));
    }
  }

  async getJobStatus(jobId: string): Promise<{
    status: string;
    trackingNumber?: string;
    deliveryDate?: string;
  }> {
    if (!this.apiKey) {
      throw new Error("Click2Mail API key not configured");
    }

    try {
      const response = await fetch(`${this.baseUrl}/jobs/${jobId}`, {
        headers: {
          "Authorization": `Bearer ${this.apiKey}`,
        },
      });

      if (!response.ok) {
        throw new Error(`Click2Mail API error: ${response.status} ${response.statusText}`);
      }

      const result = await response.json();

      return {
        status: result.status,
        trackingNumber: result.trackingNumber,
        deliveryDate: result.deliveryDate,
      };
    } catch (error: any) {
      console.error("Error getting job status from Click2Mail:", error);
      throw new Error("Failed to get job status: " + (error?.message || "Unknown error"));
    }
  }

  async submitLetter(params: {
    recipientName: string;
    recipientAddress: string;
    recipientCity: string;
    recipientState: string;
    recipientZip: string;
    pdfUrl: string;
  }): Promise<string> {
    const returnAddress = process.env.C2M_RETURN_ADDRESS_JSON
      ? JSON.parse(process.env.C2M_RETURN_ADDRESS_JSON)
      : {
          name: "Personal Credit Pros",
          address1: "123 Main St",
          city: "Anytown",
          state: "CA",
          zip: "12345",
        };

    const letter: Click2MailLetter = {
      addressFrom: returnAddress,
      addressTo: {
        name: params.recipientName,
        address1: params.recipientAddress,
        city: params.recipientCity,
        state: params.recipientState,
        zip: params.recipientZip,
      },
      document: "", // In production, load and encode PDF from params.pdfUrl
    };

    const result = await this.sendLetter(letter);
    return result.jobId;
  }
}

export const click2mailService = new Click2MailService();

