                      data-testid={`remail-${letter.id}`}
                    >
                      <RefreshCw className="w-4 h-4 mr-1" />
                      Re-mail
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

