    `;

    await this.sendEmail(userEmail, subject, message);
  }

  async sendDay34FollowUp(
    userEmail: string,
    userName: string,
    bureau: string,
    round: number,
    yesToken: string,
    noToken: string,
    uploadToken: string
  ): Promise<void> {
