                        Generate Letter
                      </Button>
                    </div>
                  );
                })}
              </div>
              <div className="text-center">
                <Button size="lg" data-testid="button-generate-all">
                  Generate All Letters
                </Button>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

