  const { user } = useAuth();
  const { toast } = useToast();
  const [isLoadingDIY, setIsLoadingDIY] = useState(false);
  const [isLoadingPro, setIsLoadingPro] = useState(false);

  const handleSelectPlan = async (plan: 'DIY' | 'DONE_FOR_YOU') => {
