import { QueryClient, QueryFunction } from "@tanstack/react-query";

async function throwIfResNotOk(res: Response) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    throw new Error(`${res.status}: ${text}`);
  }
}

export async function apiRequest(
  method: string,
  url: string,
  data?: unknown | undefined,
): Promise<Response> {
  const res = await fetch(url, {
    method,
    headers: data ? { "Content-Type": "application/json" } : {},
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  await throwIfResNotOk(res);
  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const res = await fetch(queryKey.join("/") as string, {
      credentials: "include",
    });

    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
      return null;
    }

    await throwIfResNotOk(res);
    return await res.json();
  };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: getQueryFn({ on401: "throw" }),
      refetchInterval: false,
      refetchOnWindowFocus: false,
      staleTime: Infinity,
      retry: false,
    },
    mutations: {
      retry: false,
    },
  },
});

export type Role = "user" | "admin";
export type Action = 
  | "credit_reports:read"
  | "credit_reports:write"
  | "violations:read"
  | "dispute_letters:read"
  | "dispute_letters:write"
  | "admin:users:read"
  | "admin:users:write"
  | "admin:stats:read"
  | "admin:audit:read";

const permissions: Record<Role, Action[]> = {
  user: [
    "credit_reports:read",
    "credit_reports:write",
    "violations:read",
    "dispute_letters:read",
    "dispute_letters:write"
  ],
  admin: [
    "credit_reports:read",
    "credit_reports:write",
    "violations:read",
    "dispute_letters:read",
    "dispute_letters:write",
    "admin:users:read",
    "admin:users:write",
    "admin:stats:read",
    "admin:audit:read"
  ]
};

export function can(role: Role, action: Action): boolean {
  return permissions[role]?.includes(action) || false;
}

import { Switch, Route } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import { useAuth } from "@/hooks/useAuth";
import NotFound from "@/pages/not-found";
import Landing from "@/pages/landing";
import Dashboard from "@/pages/dashboard";
import ProfilePage from "@/pages/profile";
import Analysis from "@/pages/analysis";
import Letters from "@/pages/letters";
import Subscribe from "@/pages/subscribe";
import AdminOverview from "@/pages/admin/index";
import AdminUsers from "@/pages/admin/users";
import AdminCases from "@/pages/admin/cases";
import AdminLetters from "@/pages/admin/letters";
import AdminResponses from "@/pages/admin/responses";
import AdminAudit from "@/pages/admin/audit";
import AdminBulk from "@/pages/admin/bulk";
import AdminCase from "@/pages/admin/case";

function Router() {
  const { isAuthenticated, isLoading } = useAuth();

  return (
    <Switch>
      <Route path="/subscribe" component={Subscribe} />
      {isLoading || !isAuthenticated ? (
        <Route path="/" component={Landing} />
      ) : (
        <>
          <Route path="/" component={Dashboard} />
          <Route path="/dashboard" component={Dashboard} />
          <Route path="/profile" component={ProfilePage} />
          <Route path="/analysis" component={Analysis} />
          <Route path="/letters" component={Letters} />
          <Route path="/upload" component={Dashboard} />
          <Route path="/admin" component={AdminOverview} />
          <Route path="/admin/users" component={AdminUsers} />
          <Route path="/admin/cases" component={AdminCases} />
          <Route path="/admin/case/:id" component={AdminCase} />
          <Route path="/admin/letters" component={AdminLetters} />
          <Route path="/admin/responses" component={AdminResponses} />
          <Route path="/admin/audit" component={AdminAudit} />
          <Route path="/admin/bulk" component={AdminBulk} />
        </>
      )}
      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Toaster />
        <Router />
      </TooltipProvider>
    </QueryClientProvider>
  );
}

