import express, { type Express } from "express";
import Stripe from "stripe";
import { storage } from "./storage";
import { notificationService } from "./services/notificationService";

const stripe = process.env.STRIPE_SECRET_KEY 
  ? new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2025-08-27.basil',
    })
  : null;

export function registerStripeWebhook(app: Express) {
  app.post(
    '/api/stripe/webhook',
    express.raw({ type: 'application/json' }),
    async (req, res) => {
      if (!stripe) {
        console.error('Stripe not configured - STRIPE_SECRET_KEY missing');
        return res.status(503).send('Stripe not configured');
      }

      const sig = req.headers['stripe-signature'];
      if (!sig) {
        console.error('Missing stripe-signature header');
        return res.status(400).send('Missing stripe-signature header');
      }

      const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET_SNAPSHOT || 
                           process.env.STRIPE_WEBHOOK_SECRET_THIN;

      if (!webhookSecret) {
        console.error('Stripe webhook secret not configured - add STRIPE_WEBHOOK_SECRET_SNAPSHOT or STRIPE_WEBHOOK_SECRET_THIN');
        return res.status(503).send('Webhook secret not configured');
      }

      let event: Stripe.Event;

      try {
        event = stripe.webhooks.constructEvent(
          req.body,
          sig,
          webhookSecret
        );
      } catch (err: any) {
        console.error('❌ Webhook signature verification failed:', err.message);
        return res.status(400).send(`Webhook Error: ${err.message}`);
      }

      console.log(`✓ Stripe webhook received: ${event.type}`);

      try {
        switch (event.type) {
          case 'checkout.session.completed': {
            const session = event.data.object as Stripe.Checkout.Session;
            const customerEmail = session.customer_email || session.customer_details?.email;
            const customerId = session.customer as string;
            const subscriptionId = session.subscription as string;

            if (customerEmail && customerId) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user) {
                await storage.updateUserStripeInfo(user.id, customerId, subscriptionId);
                await storage.updateUserPlan(user.id, "DONE_FOR_YOU");
                console.log(`✓ User ${user.email} upgraded to DONE_FOR_YOU via Stripe`);

                if (user.email) {
                  await notificationService.sendUpgradeConfirmation(
                    user.email,
                    user.firstName || 'User'
                  );
                }
              }
            }
            break;
          }

          case 'invoice.paid': {
            const invoice = event.data.object as Stripe.Invoice;
            const customerEmail = invoice.customer_email;

            if (customerEmail) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user) {
                console.log(`✓ Invoice paid for user ${user.email}`);
              }
            }
            break;
          }

          case 'invoice.payment_failed': {
            const invoice = event.data.object as Stripe.Invoice;
            const customerEmail = invoice.customer_email;

            if (customerEmail) {
              const user = await storage.getUserByEmail(customerEmail);
              if (user && user.email) {
                console.log(`⚠ Payment failed for user ${user.email}`);
              }
            }
            break;
          }

          case 'customer.subscription.deleted': {
            const subscription = event.data.object as Stripe.Subscription;
            const customerId = subscription.customer as string;

            const users = await storage.getAllUsers();
            const user = users.find(u => u.stripeCustomerId === customerId);

            if (user) {
              await storage.updateUserPlan(user.id, "DIY");
              console.log(`✓ User ${user.email} downgraded to DIY due to subscription cancellation`);
            }
            break;
          }

          default:
            console.log(`Unhandled Stripe event type: ${event.type}`);
        }

        res.json({ received: true });
      } catch (error) {
        console.error('❌ Error processing webhook:', error);
        res.status(500).json({ error: 'Webhook processing failed' });
      }
    }
  );
}

import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { registerStripeWebhook } from "./stripeWebhook";
import { registerClick2MailWebhook } from "./click2mailWebhook";
import "./scheduler";
import { setupVite, serveStatic, log } from "./vite";
import path from "path";
import fs from "fs";
import { requestId } from "./middleware/requestId";
import { errorHandler } from "./middleware/errorHandler";
import { rateLimit } from "./middleware/rateLimit";
import { testAuth } from "./middleware/testAuth";
import { registerObservability } from "./observability";
import { registerOpenApi } from "./openapi";

const app = express();

// Webhooks MUST be registered BEFORE express.json() 
// so they can receive raw body for signature verification
registerStripeWebhook(app);
registerClick2MailWebhook(app);

app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// Attach requestId early
app.use(requestId);

// Enable test-only auth shim
app.use(testAuth);

const FILES_DIR = process.env.FILES_DIR || path.join(process.cwd(), "files");
if (!fs.existsSync(FILES_DIR)) fs.mkdirSync(FILES_DIR, { recursive: true });
app.use("/files", express.static(FILES_DIR));

// Simple rate limit for AI/chat endpoints
app.use("/api/chat", rateLimit({ windowMs: 60_000, max: 30 }));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  // Docs & Observability
  registerOpenApi(app);
  registerObservability(app);

  // Admin bootstrap: promote users in ADMIN_EMAILS to admin role
  if (process.env.ADMIN_EMAILS) {
    const { db } = await import("./db");
    const { users } = await import("@shared/schema");
    const { eq } = await import("drizzle-orm");

    const adminEmails = process.env.ADMIN_EMAILS.split(',').map(e => e.trim());
    for (const email of adminEmails) {
      try {
        await db.update(users)
          .set({ role: 'admin' })
          .where(eq(users.email, email));
        log(`Promoted ${email} to admin`);
      } catch (e) {
        // User might not exist yet, will be promoted on login
      }
    }
  }

  // Error handler must be last
  app.use(errorHandler);

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

export { app };

import { fromBuffer } from "pdf2pic";
import Tesseract from "tesseract.js";
import fs from "fs";
import path from "path";
import fetch from "node-fetch";

export async function ocrPdfOrImage(absPath: string): Promise<string> {
  const ext = path.extname(absPath).toLowerCase();
  if (ext === ".pdf") {
    const convert = fromBuffer(fs.readFileSync(absPath), { density: 200, format: "png" });
    const pages = await convert.bulk(-1);
    let text = "";
    for (const p of pages) {
      const res = await Tesseract.recognize(p.base64, "eng");
      text += res.data.text + "\n";
    }
    return text.trim();
  } else {
    const res = await Tesseract.recognize(absPath, "eng");
    return res.data.text.trim();
  }
}

export async function ollamaGenerate(model: string, prompt: string): Promise<string> {
  const r = await fetch("http://127.0.0.1:11434/api/generate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, prompt, stream: false })
  });
  const j = await r.json();
  return j.response?.trim() || "";
}

